const pdfBtn = document.getElementById("btn-export-pdf");
if (pdfBtn) {
  pdfBtn.addEventListener("click", () => {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();
    const content = document.getElementById("report-content");

    if (!content) {
      alert("No report content found.");
      return;
    }

    html2canvas(content).then(canvas => {
      const imgData = canvas.toDataURL("image/png");
      const imgProps = doc.getImageProperties(imgData);
      const pdfWidth = doc.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

      doc.addImage(imgData, "PNG", 0, 0, pdfWidth, pdfHeight);
      doc.save("scan_results.pdf");
    });
  });
}

document.getElementById("btn-export-csv").addEventListener("click", () => {
  let csv = "Section,Key,Value\n";
  const resultEl = document.getElementById("result_display");

  if (!resultEl) {
    alert("No results to export.");
    return;
  }

  const sectionHeaders = resultEl.querySelectorAll("h3");
  sectionHeaders.forEach((section) => {
    let currentSection = section.textContent.trim();
    let next = section.nextElementSibling;

    while (next && next.tagName !== "H3") {
      if (next.tagName === "P") {
        const line = next.innerText.trim();
        if (line.includes(":")) {
          const [key, ...value] = line.split(":");
          csv += `"${currentSection}","${key.trim()}","${value.join(':').trim()}"\n`;
        } else {
          csv += `"${currentSection}","","${line}"\n`;
        }
      }
      next = next.nextElementSibling;
    }
  });

  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.setAttribute("download", "vulnerability_report.csv");
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
});
